{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 10^5",
      "description": "The number of planets is between 1 and 10^5, inclusive."
    },
    {
      "id": "P2",
      "expression": "1 <= q <= 10^5",
      "description": "The number of plans is between 1 and 10^5, inclusive."
    },
    {
      "id": "P3",
      "expression": "1 <= s <= n",
      "description": "The index of the earth is between 1 and n, inclusive."
    },
    {
      "id": "P4",
      "expression": "1 <= t <= 3",
      "description": "The type of the plan is between 1 and 3, inclusive."
    },
    {
      "id": "P5",
      "expression": "1 <= v, u, l, r <= n",
      "description": "The indices of the planets are between 1 and n, inclusive."
    },
    {
      "id": "P6",
      "expression": "1 <= w <= 10^9",
      "description": "The cost of the plan is between 1 and 10^9, inclusive."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(output) == n",
      "description": "The output contains n integers, one for each planet."
    },
    {
      "id": "Q2",
      "expression": "output[i-1] == 0 if i == s else output[i-1] >= 0",
      "description": "The cost to get from the earth to the earth is 0, and for all other planets it is the minimum cost to get there, or -1 if it is impossible."
    },
    {
      "id": "Q3",
      "expression": "all(output[i] == -1 or output[i] >= 0 for i in range(n))",
      "description": "All outputs are either the minimum cost to get to that planet or -1 if it is impossible."
    }
  ],
  "invariants": []
}
